      "technique_name": "Drive-by Compromise",
      "evidence_quote": "FBI observed actors obtaining initial access via drive-by download from compromised legitimate websites, which is an uncommon method among ransomware groups."
    },
    {
      "technique_id": "T1059.001",
      "technique_name": "Command and Scripting Interpreter: PowerShell",
      "evidence_quote": "The CAPTCHA contains instructions for users to open the Windows Run window, paste the clipboard contents, and then execute a malicious Base64-encoded PowerShell process."
    },
    {
      "technique_id": "T1547.001",
      "technique_name": "Boot or Logon Autostart Execution: Registry Run Keys / Startup Folder",
      "evidence_quote": "execute a PowerShell script that drops a file into the Windows Startup folder. From there, the file is designed to run the RAT every time the victim logs in"
    },
    {
      "technique_id": "T1033",
      "technique_name": "System Owner/User Discovery",
      "evidence_quote": "WindowsIdentity.GetCurrent() | Returns a WindowsIdentity object that represents the current Windows user."
    },
    {
      "technique_id": "T1082",
      "technique_name": "System Information Discovery",
      "evidence_quote": "systeminfo | Displays detailed configuration information about a computer and its operating system, including operating system configuration, security information, product ID, and hardware properties."
    },
    {
      "technique_id": "T1057",
      "technique_name": "Process Discovery",
      "evidence_quote": "tasklist/svc | Lists unabridged service information for each process currently running on the local computer."
    },
    {
      "technique_id": "T1007",
      "technique_name": "System Service Discovery",
      "evidence_quote": "Get-Service | Gets objects that represent the services on a computer, including running and stopped services."
    },
    {
      "technique_id": "T1056.001",
      "technique_name": "Input Capture: Keylogging",
      "evidence_quote": "the keylogger dynamic link library (DLL) logs users’ keystrokes in a file named conhost.txt."
    },
    {
      "technique_id": "T1555.003",
      "technique_name": "Credentials from Password Stores: Credentials from Web Browsers",
      "evidence_quote": "According to open source reporting, the credential stealer collects login information and associated URLs for victims’ online accounts"
    },
    {
      "technique_id": "T1021.001",
      "technique_name": "Remote Services: Remote Desktop Protocol",
      "evidence_quote": "Interlock actors leverage compromised credentials and Remote Desktop Protocol (RDP) to move between systems."
    },
    {
      "technique_id": "T1219",
      "technique_name": "Remote Access Software",
      "evidence_quote": "They also use tools like AnyDesk to enable remote connectivity and PuTTY to assist with lateral movement."
    },
    {
      "technique_id": "T1567.002",
      "technique_name": "Exfiltration Over Web Service: Exfiltration to Cloud Storage",
      "evidence_quote": "According to open source reporting, Interlock actors execute AzCopy to exfiltrate data by uploading it to the Azure storage blob."
    },
    {
      "technique_id": "T1486",
      "technique_name": "Data Encrypted for Impact",
      "evidence_quote": "Encryptors are designed to encrypt files using a combined Advanced Encryption Standard (AES) and Rivest-Shamir-Adleman (RSA) algorithm."
    },
    {
      "technique_id": "T1070.004",
      "technique_name": "Indicator Removal: File Deletion",
      "evidence_quote": "tmp41.wasd—executed after encryption using rundll32.exe—which uses the remove() function to delete the encryption binary; on Linux machines, the encryptor uses a similar technique to execute the removeme function."
    },
    {
      "technique_id": "T1218.011",
      "technique_name": "System Binary Proxy Execution: Rundll32",
      "evidence_quote": "A cybersecurity company identified a DLL binary named tmp41.wasd—executed after encryption using rundll32.exe—which uses the remove() function to delete the encryption binary"
    },
    {
      "technique_id": "T1484.001",
      "technique_name": "Domain Policy Modification: Group Policy Modification",
      "evidence_quote": "Encrypted files are appended with either a .interlock or .1nt3rlock file extension, alongside a ransom note titled !__README__!.txt delivered via group policy object (GPO)."
    }
  ]
}
